#!/usr/bin/env python3
# Generated By: Claude Code (Claude Opus 5)
#
# Strip a copy of the host's ~/.claude/settings.json down to what a sandbox
# should run with, in place. Called by sandbox.sh on the staged copy, never on
# the host's own file.
#
# Also runs on the staged copy of ~/.codex/hooks.json. That file has the same
# top-level "hooks" shape, so strip_hooks() covers it unchanged; its
# permissions and env passes find nothing and do nothing. Both harnesses then
# declare hook retention exactly one way, which is the point.
#
# Usage: strip-settings.py <settings.json|hooks.json> <host-home> [profile]

import json
import re
import sys

# Host paths mean nothing in the sandbox, where $HOME is /sandbox.
SANDBOX_HOME = "/sandbox"

# Profiles that carry no work credentials. home is personal plus Prometheus
# and Loki reads — a network policy difference, nothing to do with settings.
# Mirrors personal_profile() in scripts/lib.sh; keep the two in step.
PERSONAL_PROFILES = ("personal", "home")

# A hook whose command carries a `# KEEP:` comment survives stripping. The hook
# declares its own retention instead of this file naming it, so a new hook that
# must reach a sandbox is a change where the hook is defined and no change here.
#
# It is a shell comment, and it has to be. The obvious place for this was a
# `_keep` key on the hook object, and that silently does not work: Claude Code
# rewrites settings.json (adding `skipDangerousModePermissionPrompt`, persisting
# a plugin toggle) and drops unrecognised keys nested inside hook objects and
# rule entries. Unknown keys at the TOP level survive, which is why `_source`
# does and a nested marker does not. Measured, not assumed: seeded 19 marked
# hooks, ran `claude plugin disable`, 0 markers left. `claude doctor` does not
# show this -- it only reads, so it proves tolerance, never persistence.
#
# The command string does survive that rewrite, and hook commands are run
# through a shell, so the comment never reaches the program: a probe hook with a
# trailing `# KEEP:` reported argc=0. A dummy argument would survive equally
# well but would land in argv of a real hook like Codex's observe-hook.py.
#
# Matching is deliberately lenient -- `# KEEP` with no reason still retains the
# hook. A stricter rule would silently strip a hook someone meant to keep, and
# silence is the failure being designed out. Tests in the config repos are what
# require the reason.
KEEP_MARKER_RE = re.compile(r"#\s*KEEP\b")


def strip_permissions(settings):
    if isinstance(settings.get("permissions"), dict):
        settings["permissions"].pop("allow", None)


def strip_env(settings, profile):
    """Drop settings.json's env block entirely.

    A sandbox has exactly one env-injection path: exported OPENSHELL_SANDBOX_*
    on the host at create/refresh (docs/environment-variables.md). A settings
    file that patched its own env would be a second, unlisted one — and the
    host pins models and provider credentials in it for host reasons, neither of
    which a sandbox should inherit by accident. The profile is unused here now;
    it stays in the signature because hooks and permissions still key on it.
    """
    settings.pop("env", None)


def strip_model(settings, profile):
    # The top-level `model` is the same host pin as MODEL_KEYS, and on a
    # provider host it names a model that only exists behind ANTHROPIC_BASE_URL.
    # Personal and home have no provider, and the wrapper passes --model for
    # them anyway, so the host's value can only be wrong here. Work keeps it:
    # the model and the provider it belongs to travel together.
    if profile in PERSONAL_PROFILES:
        settings.pop("model", None)


def keep_hook(hook):
    """Whether one hook object survives stripping."""
    return isinstance(hook, dict) and bool(KEEP_MARKER_RE.search(hook.get("command", "")))


def strip_hooks(settings):
    hooks = settings.get("hooks")
    if not isinstance(hooks, dict):
        settings.pop("hooks", None)
        return
    for event in list(hooks.keys()):
        rules = hooks[event]
        if not isinstance(rules, list):
            continue
        # Filtered per hook, not per rule entry. Keeping the whole entry
        # because one hook in it qualified is how an unmarked hook used to
        # reach a sandbox by sharing an entry with a marked one — silent, and
        # it made "give it its own entry" a rule every hook author had to know.
        kept = []
        for rule in rules:
            if not isinstance(rule, dict):
                continue
            inner = [h for h in rule.get("hooks", []) if keep_hook(h)]
            if inner:
                kept.append(dict(rule, hooks=inner))
        if kept:
            hooks[event] = kept
        else:
            del hooks[event]
    if not hooks:
        del settings["hooks"]


def main():
    if len(sys.argv) < 3:
        print(
            "Usage: strip-settings.py <settings.json|hooks.json> <host-home> [profile]",
            file=sys.stderr,
        )
        sys.exit(1)

    path, host_home = sys.argv[1], sys.argv[2]
    profile = sys.argv[3] if len(sys.argv) > 3 else ""

    with open(path, "r") as f:
        raw = f.read()
    settings = json.loads(raw.replace(host_home, SANDBOX_HOME))

    strip_permissions(settings)
    strip_env(settings, profile)
    strip_model(settings, profile)
    strip_hooks(settings)

    with open(path, "w") as f:
        json.dump(settings, f, indent=2)


if __name__ == "__main__":
    main()
